import numpy as np
for i in [6,7]:
    I=np.array(G[f'Demo pair {i} input']); O=np.array(G[f'Demo pair {i} output'])
    from collections import Counter
    cnt=Counter(int(v) for r in I for v in r); bg=cnt.most_common(1)[0][0]
    rest={c:n for c,n in cnt.items() if c!=bg}
    objcol=max(rest,key=lambda c:rest[c]); markcol=[c for c in rest if c!=objcol][0]
    ob=[(a,b) for a in range(I.shape[0]) for b in range(I.shape[1]) if I[a,b]==objcol]
    marks=[(a,b) for a in range(I.shape[0]) for b in range(I.shape[1]) if I[a,b]==markcol]
    rs=[p[0] for p in ob]; cs_=[p[1] for p in ob]
    h,w=I.shape
    sh=max(rs)-min(rs)+1; sw=max(cs_)-min(cs_)+1
    adds={(a,b) for a in range(h) for b in range(w) if I[a,b]!=O[a,b]}
    cands=[]
    for dr in range(-h,h+5):
        for dc in range(-w,w+5):
            tp=frozenset((a+dr,b+dc) for a,b in ob)
            if adds<=tp and len(tp&adds)>=len(adds)*0.9:
                cands.append((dr,dc,len(tp&adds)))
    print(i,'bbox',sh,sw,'markers',marks,'cover-cands',cands[:5])
